def cheapest_network(n: int, links: list[list[int]]) -> int:
    chosen = [[] for _ in range(n)]              # adjacency of the cables picked so far
    total, picked = 0, 0
    for a, b, cost in sorted(links, key=lambda link: link[2]):
        seen, stack = {a}, [a]                   # DFS: is b already reachable from a?
        while stack:
            for nxt in chosen[stack.pop()]:
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        if b in seen:
            continue
        chosen[a].append(b)
        chosen[b].append(a)
        total += cost
        picked += 1
    return total if picked == n - 1 else -1
